445		)
446			throw new Error('pigallery2 holdout finding or support boundary differs');
447		if (
448			!Array.isArray(receipt.nonclaims) ||
449			!HOLDOUT_ANGULAR_PIGALLERY2_ADDED_NONCLAIMS.every((claim) =>
450				receipt.nonclaims.includes(claim),
451			)
452		)
453			throw new Error('pigallery2 holdout non-claims differ');
454		if (
455			receipt.integrity?.algorithm !== 'sha256' ||
456			!sha256Hex.test(receipt.integrity.canonicalDigest) ||
457			receipt.integrity.canonicalDigest !== holdoutAngularPigallery2Digest(receipt)
458		)
459			throw new Error('pigallery2 holdout integrity differs');
460		return receipt;
461	}
462	
463	export function renderHoldoutAngularPigallery2Receipt(
464		receipt: HoldoutAngularPigallery2Receipt,
465	): string {
466		const boundary = receipt.supportBoundary;
467		return `# pigallery2 1.7.0 — Angular holdout falsification receipt
468	
469	- Outcome: **${receipt.holdoutOutcome}** — the frozen Angular adapter does not carry this application at this revision
470	- Recorded reason: **${receipt.reason}**
471	- Canonical SHA-256: ${receipt.integrity.canonicalDigest}
472	- Ingested by \`${receipt.ingestUnit}\`, measured at the wall by \`${receipt.measuringUnit}\`, published by \`${receipt.publishedBy}\`
473	- Source: ${receipt.source.repository} at release \`${receipt.source.release}\` (\`${receipt.source.revision}\`, ${receipt.source.license}, license text sha256 \`${receipt.source.licenseSha256}\`), Angular ${receipt.source.angular} under ${receipt.source.angularCli}, TypeScript ${receipt.source.typescript}
474	- Target cell: \`${receipt.cell.id}\` — Angular ${receipt.cell.angularLine}, \`${receipt.cell.builder}\`
475	- Adapter at ingestion: frozen composite \`${receipt.frozenAdapter.compositeFingerprintAtIngestion}\`, ${receipt.frozenAdapter.bytesChangedAtIngestion} bytes changed; ${receipt.frozenAdapter.applicationFilesHandEdited} application files hand-edited
476	- Authorized reopen: ${receipt.frozenAdapter.authorizedReopen.statement}
477	- Derived from committed run evidence: ${receipt.runEvidence.map((item) => `\`${item.path}\` (\`${item.sha256}\`)`).join(', ')}
478	
479	## Both lanes
480	
481	- Baseline (${receipt.lanes.baseline.toolchain}): **${receipt.lanes.baseline.outcome}** — ${receipt.lanes.baseline.statement}
482	- Migrated: **${receipt.lanes.migrated.outcome}** — closure installs, ${receipt.lanes.migrated.buildsAttempted} builds attempted, ${receipt.lanes.migrated.diagnosticsBeforeWall} diagnostics before the last capability pass and ${receipt.lanes.migrated.diagnosticsAtWall} at the wall, no artifact produced. ${receipt.lanes.migrated.statement}
483	
484	## The wall
485	
486	**${receipt.finding.missingCapability}.**
487	
488	${receipt.finding.statement}
489	
490	${receipt.finding.wall.map((entry) => `- \`${entry.library}\` — ${entry.verdict}. Import sites: ${entry.importSites.map((site) => `\`${site}\``).join(', ')}.`).join('\n')}
491	
492	${receipt.finding.libraries} libraries at ${receipt.finding.importSites} import sites. ${receipt.finding.downstreamReading}
493	
494	Action taken: ${receipt.finding.actionTaken}
495	
496	## Declared support boundary
497	
498	**${boundary.condition}**
499	
500	- State: **${boundary.state}** at cell \`${boundary.cell}\` (${boundary.lineage} lineage)
501	- Declared by ${boundary.declaredBy}; published by \`${boundary.publishedBy}\`
502	- Mechanism: ${boundary.mechanism}
503	- Certification: ${boundary.certification}
504	
505	${boundary.nonclaims.map((claim) => `- ${claim}`).join('\n')}
506	
507	## Non-claims
508	
509	${receipt.nonclaims.map((claim) => `- ${claim}`).join('\n')}
510	`;
511	}
512	
513	/**
514	 * The corpus and aggregate record for this holdout.
515	 *
516	 * It follows the cypress-realworld-app record field for field: a holdout that
517	 * failed is evidence about the adapter, not a migrated application, so it is
518	 * never an aggregate fixture row and never a Judge counting cell, and
519	 * `countedInLineageNumerator` is false and stays false.
520	 */
521	export function holdoutAngularPigallery2CorpusRecord(receipt: HoldoutAngularPigallery2Receipt) {
522		return {
523			id: 'holdout-angular-pigallery2',
524			application: receipt.application,
525			framework: receipt.framework,
526			lineage: 'angular',
527			role: 'holdout',
528			attempted: true,
529			outcome: receipt.holdoutOutcome,
530			reason: receipt.reason,
531			verdict: receipt.finding.verdict,
532			frozenAdapterFingerprint: receipt.frozenAdapter.compositeFingerprintAtIngestion,
533			adapterBytesChanged: receipt.frozenAdapter.bytesChangedAtIngestion,
534			authorizedReopen: {
535				task: receipt.frozenAdapter.authorizedReopen.task,
536				subtree: receipt.frozenAdapter.authorizedReopen.subtree,
537				capabilitiesExtracted: receipt.frozenAdapter.authorizedReopen.capabilitiesExtracted,
538				angularSubtreeOidAtWall: receipt.frozenAdapter.authorizedReopen.angularSubtreeOidAtWall,
539				outcomeAfterReopen: 'failed',
540			},
541			baselineLane: receipt.lanes.baseline.outcome,
542			migratedLane: receipt.lanes.migrated.outcome,
543			attempts: receipt.lanes.migrated.buildsAttempted,
544			receipt: HOLDOUT_ANGULAR_PIGALLERY2_RECEIPT_PATH,
545			digest: receipt.integrity.canonicalDigest,
546			countedInLineageNumerator: false,
547			countingNote:
548				'Never counted in any lineage numerator: no application was migrated. The record is published rather than dropped so a failed falsification attempt cannot be hidden, and it is not reclassified by the support boundary it established.',
549			supportBoundary: ANGULAR_PRE_IVY_SUPPORT_BOUNDARY.id,
550			browserProof: 'not-tested',
551		};
552	}
553	
554	export async function verifyHoldoutAngularPigallery2Evidence(rootDir = '.'): Promise<{
555		valid: true;
556		digest: string;
557		artifacts: number;
558		receipt: HoldoutAngularPigallery2Receipt;
559	}> {
560		const root = resolve(rootDir);
561		const published = parseHoldoutAngularPigallery2Receipt(
562			JSON.parse(await readFile(join(root, HOLDOUT_ANGULAR_PIGALLERY2_RECEIPT_PATH), 'utf8')),
563		);
564		const derived = await deriveHoldoutAngularPigallery2Receipt(root);
565		if (canonicalize(published) !== canonicalize(derived))
566			throw new Error('pigallery2 holdout receipt does not match its committed run evidence');
567		if (
568			(await readFile(join(root, HOLDOUT_ANGULAR_PIGALLERY2_MARKDOWN_PATH), 'utf8')) !==
569			renderHoldoutAngularPigallery2Receipt(published)
570		)
571			throw new Error('pigallery2 holdout human receipt differs');
572		return {
573			valid: true as const,
574			digest: published.integrity.canonicalDigest,
575			artifacts: published.runEvidence.length,
576			receipt: published,
577		};
578	}
