const extractDir = join(OUT, 'extract');
await mkdir(extractDir, { recursive: true });
execFileSync('tar', ['-xzf', join(OUT, 'archive-1.tar.gz'), '-C', extractDir]);
const roots = await readdir(extractDir);
if (roots.length !== 1) throw new Error(`archive has ${roots.length} roots`);
const rootDir = join(extractDir, roots[0]);

async function walk(dir, acc = []) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) await walk(full, acc);
    else acc.push(full);
  }
  return acc;
}
const files = await walk(rootDir);
let regularFiles = 0;
let symlinks = 0;
const measured = new Map();
for (const file of files) {
  const info = await lstat(file);
  const rel = relative(rootDir, file);
  if (info.isSymbolicLink()) { symlinks += 1; continue; }
  regularFiles += 1;
  const bytes = await readFile(file);
  const header = Buffer.from(`blob ${bytes.length}\0`, 'utf8');
  measured.set(rel, createHash('sha1').update(Buffer.concat([header, bytes])).digest('hex'));
}
let missing = 0, mismatched = 0;
const mismatchSamples = [];
for (const entry of blobs) {
  const got = measured.get(entry.path);
  if (got === undefined) { missing += 1; if (mismatchSamples.length < 5) mismatchSamples.push({ path: entry.path, reason: 'missing' }); continue; }
  if (got !== entry.sha) { mismatched += 1; if (mismatchSamples.length < 5) mismatchSamples.push({ path: entry.path, tree: entry.sha, measured: got }); }
}
const treePaths = new Set(blobs.map((e) => e.path));
let extra = 0;
for (const rel of measured.keys()) if (!treePaths.has(rel)) extra += 1;

const subBlobs = blobs.filter((e) => e.path === SUBPATH || e.path.startsWith(`${SUBPATH}/`));
const subDirs = tree.tree.filter((e) => e.type === 'tree' && (e.path === SUBPATH || e.path.startsWith(`${SUBPATH}/`)));
let subBytes = 0;
for (const entry of subBlobs) subBytes += (await stat(join(rootDir, entry.path))).size;

const result = {
  repository: { id: repo.id, fullName: repo.full_name, private: repo.private, archived: repo.archived, disabled: repo.disabled, defaultBranch: repo.default_branch, license: repo.license, responseBytes: requests[0].bytes, responseSha256: requests[0].sha256 },
  ref: { ref: ref.ref, objectType: ref.object.type, objectSha: ref.object.sha },
  tagObject: tagObject ? { sha: tagObject.sha, tagger: tagObject.tagger, verification: tagObject.verification?.verified, message: tagObject.message } : null,
  commit: { sha: commit.sha, date: commit.committer?.date, authorDate: commit.author?.date, verified: commit.verification?.verified, treeSha: commit.tree.sha, message: commit.message },
  tree: { sha: TREE, truncated: tree.truncated, entries: tree.tree.length, blobs: blobs.length, directories: tree.tree.filter((e) => e.type === 'tree').length, symlinks: tree.tree.filter((e) => e.mode === '120000').length, gitlinks: tree.tree.filter((e) => e.type === 'commit').length },
  license: { path: 'LICENSE', blobSha1: licenseEntry.sha, bytes: licenseText.length, sha256: sha256(licenseText), firstLines: licenseText.toString('utf8').split('\n').slice(0, 3) },
  archive: { url: archiveUrl, streams, byteIdentical, root: roots[0] },
  parity: { treeBlobs: blobs.length, extractedRegularFiles: regularFiles, extractedSymlinks: symlinks, missing, mismatched, extra, mismatchSamples },
  subpath: { path: SUBPATH, blobs: subBlobs.length, directories: subDirs.length, bytes: subBytes, shareOfTreeBlobs: `${subBlobs.length}/${blobs.length}` },
  requests,
  extractedAt: rootDir,
};
await writeFile(join(OUT, 'acquire-result.json'), `${JSON.stringify(result, null, 2)}\n`);
console.log('ACQUIRE OK');
console.log(JSON.stringify({ repository: result.repository, ref: result.ref, commit: { sha: result.commit.sha, date: result.commit.date }, tree: result.tree, license: result.license, archive: { url: archiveUrl, streams, byteIdentical }, parity: result.parity, subpath: result.subpath }, null, 2));
